<?php
require_once __DIR__ . '/../verifica_login.php'; require_once __DIR__ . '/../conexao.php'; require_once __DIR__ . '/../_layout.php';
$modulos=require __DIR__.'/../config_crud/modulos.php'; verify_csrf();
$modulo=$_POST['modulo']??''; if(!isset($modulos[$modulo])) exit('Módulo inválido.'); $c=$modulos[$modulo]; $t=$c['tabela']; $k=$c['chave'];
$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); $dados=[];
foreach($c['campos'] as $campo=>$cfg){ $v=trim((string)($_POST[$campo]??'')); if(!empty($cfg['obrigatorio'])&&$v===''){flash('erro','Preencha o campo '.$cfg['label'].'.'); redirect('index.php?modulo='.$modulo.($id?'&editar='.$id:'&novo=1'));} if($cfg['tipo']==='number'&&$v!==''&&!is_numeric($v)){flash('erro','Valor inválido em '.$cfg['label'].'.'); redirect('index.php?modulo='.$modulo.($id?'&editar='.$id:'&novo=1'));} $dados[$campo]=$v;}
try { if($id){$set=[];$vals=[];$types='';foreach($dados as $campo=>$v){$set[]="`$campo`=?";$vals[]=$v;$types.='s';}$vals[]=$id;$types.='i';$sql="UPDATE `$t` SET ".implode(',',$set)." WHERE `$k`=?";$st=$conexao->prepare($sql);$st->bind_param($types,...$vals);$st->execute();$st->close();flash('ok',$c['singular'].' atualizado com sucesso.');}else{$cols=array_keys($dados);$marks=array_fill(0,count($cols),'?');$vals=array_values($dados);$types=str_repeat('s',count($vals));$sql="INSERT INTO `$t` (`".implode('`,`',$cols)."`) VALUES (".implode(',',$marks).")";$st=$conexao->prepare($sql);$st->bind_param($types,...$vals);$st->execute();$st->close();flash('ok',$c['singular'].' cadastrado com sucesso.');}}catch(Throwable $e){flash('erro','Não foi possível salvar o registro. Verifique os dados e as regras do banco.');} redirect('index.php?modulo='.$modulo);
